from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize list to store separated groups

    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                groups.append(paren_string[start:i+1])  # Step 2, 3, 4: Identify, extract, and separate balanced groups

    return groups

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

